import gzip
import numpy as np, pandas as pd

TASK = "/task"
lib = pd.read_csv(f"{TASK}/input/library.tsv", sep="\t")
samples = pd.read_csv(f"{TASK}/input/samples.tsv", sep="\t")
spacer_set = {s: i for i, s in enumerate(lib["sequence"])}
COMP = str.maketrans("ACGTN", "TGCAN")
def rc(s): return s.translate(COMP)[::-1]
SCAF = "GTTTTAGAGCTA"; RSCAF = rc(SCAF)

# per-sample mode counts
for j, row in samples.iterrows():
    path = f"{TASK}/input/fastq/{row['fastq_file']}"
    fwd = rev = fb = un = 0
    kpos = {}
    fb_examples = []
    with gzip.open(path, "rt") as fh:
        while True:
            h = fh.readline()
            if not h: break
            seq = fh.readline().strip(); fh.readline(); fh.readline()
            k = seq.find(SCAF)
            hit = False
            if k >= 20 and seq[k-20:k] in spacer_set:
                fwd += 1; kpos[k] = kpos.get(k, 0) + 1; hit = True
            else:
                k2 = seq.find(RSCAF)
                if k2 >= 0 and k2+32 <= len(seq) and rc(seq[k2+12:k2+32]) in spacer_set:
                    rev += 1; hit = True
                else:
                    r = rc(seq); found = False
                    for i in range(0, len(seq)-19):
                        if seq[i:i+20] in spacer_set or r[i:i+20] in spacer_set:
                            found = True; break
                    if found:
                        fb += 1
                        if len(fb_examples) < 3: fb_examples.append(seq)
                        hit = True
            if not hit: un += 1
    print(row["sample_id"], "fwd", fwd, "rev", rev, "fallback", fb, "unmapped", un)
    if j == 0:
        print("  LIB8 scaffold positions:", sorted(kpos.items()))
        for e in fb_examples: print("  FB>", e)
EOF
